import {mimoPaperEdge,mimoLabel} from './gift-identity.js';
import {coverOptions} from './cover-catalog.js';
import {paintStationery,ensureStationeryFonts} from './stationery.js';
import {giftArtworkSource} from './appearance.js';
import {appearancePalette} from './appearance.js';
import {downloadFile} from './experience.js';
import {drawWrapped} from './text-layout.js';
import {loadImage} from './paper.js';
import {cleanStoryDesign,storyPalettes} from './story-design.js';
const icsText=value=>String(value||'').replaceAll('\\','\\\\').replace(/\r?\n/g,'\\n').replaceAll('\r','').replaceAll(',','\\,').replaceAll(';','\\;');
export function makeDeliveryReminder(data,when){const date=new Date(when);if(!Number.isFinite(date.getTime())||date.getTime()<=Date.now())throw Error('Escolha uma data e um horário no futuro.');const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');return new Blob([['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Capimimo//Lembrete//PT-BR','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@capimimo.local','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(date),'DTEND:'+stamp(new Date(date.getTime()+15*60000)),'SUMMARY:'+icsText('Entregar mimo para '+(data.recipient||'alguém especial')),'DESCRIPTION:'+icsText('Lembrete pessoal: envie manualmente o arquivo do presente Capimimo. '+(data.delivery?.note||'')),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Hora de entregar seu mimo','TRIGGER:-PT15M','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n')],{type:'text/calendar;charset=utf-8'});}
export function initDeliveryTools({getData,getState,onChange,authorize=async()=>true}){
 const panel=document.createElement('section');panel.className='delivery-tools';panel.innerHTML='<details class="print-editor options-panel"><summary>Um quadro para imprimir</summary><p>Uma lembrança digital em tamanho A4. Escolha a foto, a composição e uma dedicatória antes de baixar.</p><div class="field"><label for="print-photo">Foto do quadro</label><select id="print-photo" aria-describedby="print-photo-status"></select><p id="print-photo-status" role="status"></p></div><div class="field"><label for="print-collection">Coleção de quadros · 30 por ocasião</label><select id="print-collection"></select></div><div class="field"><label for="print-style">Composição</label><select id="print-style"><option value="collection">Da coleção</option><option value="editorial">Retrato editorial</option><option value="polaroid">Moldura de lembrança</option><option value="full">Fotografia em destaque</option></select></div><div class="field"><label for="print-message">Dedicatória do quadro</label><textarea id="print-message" rows="3" maxlength="240" placeholder="Uma frase para guardar."></textarea></div><canvas width="2480" height="3508" class="print-preview" role="img" aria-label="Prévia do quadro A4"></canvas><div class="print-actions"><button type="button" class="download-print">Baixar quadro em PNG</button><button type="button" class="open-print">Imprimir ou salvar como PDF</button></div><p class="print-status" role="status"></p></details><details class="delivery-reminder options-panel"><summary>Preparar a entrega</summary><p>Guarde um lembrete no seu calendário para entregar o presente na hora que escolher. O arquivo não envia WhatsApp ou e-mail automaticamente.</p><div class="field"><label for="delivery-when">Quando você quer entregar?</label><input type="datetime-local" id="delivery-when"></div><div class="field"><label for="delivery-note">Uma anotação para você</label><input id="delivery-note" maxlength="180" placeholder="Ex.: enviar depois do almoço em família"></div><button type="button" class="download-reminder">Baixar lembrete do calendário</button><p class="reminder-status" role="status"></p></details>';
 document.querySelector('.digital-delivery').after(panel);const $=selector=>panel.querySelector(selector),canvas=$('canvas');let revision=0,key='',exportBusy=false,exportVersion=0;
 function settings(data=getData()){const design=getState().printDesign||{},photos=data.photos||[],hasCollection=coverOptions(getState().occasion,'livro').some(cover=>cover.id===design.coverId);return {...design,message:design.message||'',photoId:photos.some(photo=>photo.id===design.photoId)?design.photoId:photos[0]?.id||'',style:design.style==='collection'&&!hasCollection?'editorial':design.style||(hasCollection?'collection':'editorial')};}
 function patchPrint(value){onChange({printDesign:{...settings(),photoId:getState().printDesign?.photoId||'',...value}});}
 $('#print-collection').addEventListener('change',event=>patchPrint({coverId:event.target.value,style:event.target.value?'collection':'editorial'}));$('#print-photo').addEventListener('change',event=>patchPrint({photoId:event.target.value}));$('#print-style').addEventListener('change',event=>patchPrint({style:event.target.value}));$('#print-message').addEventListener('input',event=>patchPrint({message:event.target.value}));$('#delivery-when').addEventListener('change',event=>onChange({delivery:{...getState().delivery,when:event.target.value}}));$('#delivery-note').addEventListener('input',event=>onChange({delivery:{...getState().delivery,note:event.target.value}}));
 async function paint(target=canvas,snapshot=null){const own=snapshot?0:++revision,canvas=target,data=snapshot?.data||getData(),design=snapshot?.design||settings(data),palette=appearancePalette(data.format==='stories'?cleanStoryDesign(data.storyDesign):data.appearance),photo=(data.photos||[]).find(photo=>photo.id===design.photoId)||(data.photos||[])[0],image=photo?await loadImage(photo.src):null;if(!snapshot&&own!==revision)return false;await document.fonts.ready;if(!snapshot&&own!==revision)return false;const ctx=canvas.getContext('2d');const drawPrintEdge=(edgePalette=palette)=>{ctx.save();ctx.scale(2480/600,3508/800);mimoPaperEdge(ctx,600,800,edgePalette);ctx.restore();};const cover=coverOptions(data.occasion,'livro').find(item=>item.id===design.coverId);if(cover){await ensureStationeryFonts();const [pattern,sprite]=await Promise.all([loadImage(giftArtworkSource({coverArt:cover.family})),loadImage('assets/'+data.theme.sheet+'.webp')]);if(!snapshot&&own!==revision)return false;const surface=document.createElement('canvas');surface.width=1200;surface.height=1600;paintStationery(surface,{...data,format:'livro',appearance:cover.appearance,bookFinish:cover.bookFinish,stationeryDesign:{...data.stationeryDesign,layout:design.style==='collection'?cover.layout:({full:'poster',polaroid:'lembranca',editorial:'editorial'}[design.style]||cover.layout),...(design.style!=='collection'?{fit:design.style==='full'?'cover':'contain'}:{}),title:data.stationeryDesign?.title||data.theme.label},coverArt:cover.family},{photo:image,pattern,sprite});const colors=appearancePalette(cover.appearance);ctx.fillStyle=colors.paper;ctx.fillRect(0,0,2480,3508);ctx.drawImage(surface,155,70,2170,2893);ctx.fillStyle=colors.ink;ctx.textAlign='center';ctx.textBaseline='top';ctx.font='500 68px Fraunces,Georgia';drawWrapped(ctx,design.message||data.message||'Uma lembrança feita para você.',1240,3010,2100,88,4);drawPrintEdge(colors);return true;}ctx.fillStyle=palette.paper;ctx.fillRect(0,0,2480,3508);ctx.textAlign='center';const full=design.style==='full',polaroid=design.style==='polaroid';let frame=full?{x:0,y:0,w:2480,h:2650}:polaroid?{x:220,y:280,w:2040,h:2150}:{x:180,y:300,w:2120,h:2200};if(polaroid){ctx.fillStyle='#fffdf8';ctx.fillRect(140,200,2200,2600);ctx.strokeStyle=palette.ink;ctx.lineWidth=4;ctx.strokeRect(140,200,2200,2600);}ctx.fillStyle=palette.soft;ctx.fillRect(frame.x,frame.y,frame.w,frame.h);if(image){const scale=full?Math.max(frame.w/image.width,frame.h/image.height):Math.min(frame.w/image.width,frame.h/image.height),w=image.width*scale,h=image.height*scale;ctx.save();ctx.beginPath();ctx.rect(frame.x,frame.y,frame.w,frame.h);ctx.clip();ctx.drawImage(image,frame.x+(frame.w-w)/2,frame.y+(frame.h-h)/2,w,h);ctx.restore();}else{ctx.fillStyle=palette.ink;ctx.font='70px Nunito';ctx.fillText('Escolha uma foto para o quadro.',1240,1400);}ctx.fillStyle=palette.ink;ctx.font='700 112px Fraunces,Georgia';drawWrapped(ctx,design.message||data.storyDesign?.subtitle||data.message||'As melhores lembranças ficam.',1240,polaroid?2540:2820,1960,140,3);ctx.font='54px Nunito,Arial';ctx.fillStyle=palette.accent;drawWrapped(ctx,data.storyDesign?.nickname||data.recipient||'',1240,3260,1960,70,2);drawPrintEdge();return true;}
 async function preview(){const own=revision+1,exportAtStart=exportVersion;try{const painted=await paint();if(painted&&own===revision&&!exportBusy&&exportAtStart===exportVersion)$('.print-status').textContent='Prévia do quadro pronta.';}catch{if(own!==revision)return;canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);if(!exportBusy&&exportAtStart===exportVersion)$('.print-status').textContent='Não foi possível preparar a foto. Escolha outra foto e tente novamente.';}}
 $('.print-editor').addEventListener('toggle',()=>{if($('.print-editor').open)preview();});
 async function exportPrint(mode){if(exportBusy)return;exportBusy=true;exportVersion++;$('.download-print').disabled=$('.open-print').disabled=true;let printWindow=null;$('.print-status').textContent='Conferindo acesso e preparando seu quadro…';try{if(!await authorize()){$('.print-status').textContent='Confira o acesso à compra para baixar ou imprimir este quadro.';return;}const snapshot=structuredClone({data:getData(),design:settings()});if(!snapshot.data.photos?.length){$('.print-status').textContent='Adicione uma foto para criar seu quadro.';return;}if(mode==='print'){printWindow=window.open('','_blank');if(!printWindow){$('.print-status').textContent='Libere a nova janela ou baixe o PNG para imprimir.';return;}printWindow.document.title='Quadro Capimimo';}const output=document.createElement('canvas');output.width=2480;output.height=3508;await paint(output,snapshot);if(mode==='download'){const blob=await new Promise(resolve=>output.toBlob(resolve,'image/png'));if(!blob)throw Error();downloadFile('capimimo-quadro-A4-2480x3508.png',blob);$('.print-status').textContent='Quadro baixado em 2480 × 3508 pixels, proporção A4.';}else{const image=printWindow.document.createElement('img');image.src=output.toDataURL('image/png');image.alt='Quadro personalizado Capimimo';const style=printWindow.document.createElement('style');style.textContent='@page{size:A4;margin:0}body{margin:0}img{display:block;width:210mm;height:297mm;object-fit:contain}@media screen{body{background:#eee}img{max-width:100%;height:auto}}';printWindow.document.head.append(style);printWindow.document.body.append(image);await image.decode();printWindow.print();$('.print-status').textContent='Quadro pronto para imprimir ou salvar como PDF.';}}catch{printWindow?.close();$('.print-status').textContent='Não foi possível preparar o quadro. Tente novamente ou baixe o PNG para imprimir.';}finally{exportBusy=false;$('.download-print').disabled=$('.open-print').disabled=false;}}
 $('.download-print').addEventListener('click',()=>exportPrint('download'));$('.open-print').addEventListener('click',()=>exportPrint('print'));
 $('.download-reminder').addEventListener('click',()=>{try{downloadFile('capimimo-lembrete.ics',makeDeliveryReminder(getData(),$('#delivery-when').value));$('.reminder-status').textContent='Lembrete baixado. Importe no seu calendário; a entrega será feita por você.';}catch(error){$('.reminder-status').textContent=error.message;}});
 function render(){const state=getState(),design=settings(),covers=coverOptions(state.occasion,'livro');if($('#print-collection').dataset.occasion!==state.occasion){$('#print-collection').dataset.occasion=state.occasion;$('#print-collection').replaceChildren(new Option('Usar composição rápida',''),...covers.map(item=>new Option(String(item.number).padStart(2,'0')+' · '+item.name,item.id)));}$('#print-collection').value=design.coverId||'';const photos=getData().photos||[],signature=JSON.stringify(photos.map(photo=>[photo.id,photo.name]));if(signature!==key){key=signature;$('#print-photo').replaceChildren(...photos.map((photo,index)=>new Option(photo.name||'Foto '+(index+1),photo.id)));}$('#print-photo').value=design.photoId;const requestedPhotoId=state.printDesign?.photoId,missingPhoto=requestedPhotoId&&!photos.some(photo=>photo.id===requestedPhotoId);$('#print-photo-status').textContent=missingPhoto?(photos.length?'A foto escolhida não está mais disponível. Estamos usando '+(photos.find(photo=>photo.id===design.photoId)?.name||'a primeira foto')+'. Você pode escolher outra.':'A foto escolhida não está mais disponível. Adicione uma foto para criar seu quadro.'):'';const collectionStyle=$('#print-style [value=collection]');collectionStyle.disabled=collectionStyle.hidden=!covers.some(cover=>cover.id===design.coverId);if($('#print-style').value!==String(design.style))$('#print-style').value=design.style;if($('#print-message').value!==(design.message||''))$('#print-message').value=design.message||'';for(const [id,value] of [['delivery-when',state.delivery?.when||''],['delivery-note',state.delivery?.note||'']])if($('#'+id).value!==String(value))$('#'+id).value=value;if($('.print-editor').open)preview();}
 render();return {render};
}
